"""Expand explicit, source-read Batch 26 evidence; never modifies question shards."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
def read(path):
    return json.loads((ROOT / path).read_text(encoding='utf-8'))
def write(path, value):
    (ROOT / path).write_text(json.dumps(value, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

library = read('audit/source-notes.json')
def source(key, url, locator, evidence, limitation='Primary institutional text inspected; no film or video playback claimed.', changing=False):
    library['sources']['b26-' + key] = dict(url=url, locator=locator, evidence=evidence,
        checkedBy='Codex', checkedAt='2026-11-08', timeSensitive=changing,
        nextReviewAt='2027-02-05' if changing else None, limitations=limitation, topics=['Batch 26'])

