notes = read('audit/runs/next-shard-0026-final-notes.json')
checks = ['singleAnswer','context','wording','noGiveaway','distinctFact','category','difficulty','scope']
for review in notes['reviews']:
    i = review['questionId']
    sources, premise, reasons, challenge = rows[i]
    review['checks'] = checks
    review['notes'] = 'Read full topic context and all four final options; checked bank comparisons. ' + challenge
    review['context'] = ('Disney Cruise Line; dated November 2026 where current.' if 1394 <= i <= 1400 else
        'Original English-language theatrical film; historical production/award facts where stated.')
    if 1401 <= i <= 1408:
        review['notes'] += ' Turning Red has 13 topic entries; retained distinct main-theatrical facts under the soft coverage guidance.'
    if 1414 <= i <= 1417:
        review['notes'] += ' Inside Out 2 has 11 topic entries; distinct theatrical story facts justify this modest soft-cap excess.'
    review['timeSensitive'] = i in [1394,1396,1400]
    review['nextReviewAt'] = '2027-02-05' if review['timeSensitive'] else None
    review['premise'] = dict(reason=premise, sources=sources)
    review['options'] = [dict(basis='direct' if j == 0 else 'exclusive-inference', reason=r, sources=sources) for j,r in enumerate(reasons)]
    review['challenge'] = dict(reviewer='Codex',at='2026-11-08',premiseChecked=True,alternativesExcluded=True,notes=challenge)
notes['sourcesChecked'] = sorted({s for value in rows.values() for s in value[0]})
